import { atom, read, update } from 'claude-code'
import type { EngineInterface, Register, Timer } from 'claude-code'

import type { ChatIndex, Doc, Source, Thread, UiState } from '../types'
import {
  EMPTY_UI,
  TOOL_PREFIX,
  chatDoc,
  claudeIdsOf,
  clientPropsOf,
  critThreadsOf,
  emptyDoc,
  feedbackOf,
  fileDoc,
  newId,
  parseDiff,
  pendingOf,
  quoteOffsetOf,
  chatLinePrefix,
  chatMarkdownOf,
  chatPlanSlug,
  chatThreadsFromPlan,
  sectionBefore,
  selectionOf,
  whereOf,
} from './model'

type $ = EngineInterface

export const PANE = 'crit'
const MAX_UNTRACKED = 20

const threadsA = atom({ plugin: 'crit-tui', key: 'threads' } as const, [] as Thread[])
const critThreadsA = atom({ plugin: 'crit-tui', key: 'critThreads' } as const, [] as Thread[])
const sentA = atom({ plugin: 'crit-tui', key: 'sent' } as const, [] as string[])
const seenA = atom({ plugin: 'crit-tui', key: 'seen' } as const, [] as string[])
const uiA = atom({ plugin: 'crit-tui', key: 'ui' } as const, EMPTY_UI)
const chatIndexA = atom({ plugin: 'crit-tui', key: 'chatIndex' } as const, [] as ChatIndex)
const isOpenA = atom({ plugin: 'crit-tui', key: 'isOpen' } as const, false)
const docsA = atom({ plugin: 'crit-tui', key: 'docs' } as const, {
  chat: emptyDoc('chat', 'Conversation', 'Loading…'),
  diff: emptyDoc('diff', 'Diff', 'Loading…'),
  file: emptyDoc('file', 'File', 'Open a file with /crit-tui file <path>.'),
})

// Values a reload recomputes; the review itself lives in $.state.
let critBin = 'crit'
let reviewFile: string | null = null
let hasCrit = true
let diffTimer: Timer | null = null
// Chat comments live in a crit plan when the crit CLI has `plan --no-wait`.
let hasChatPlans: boolean | null = null
let chatSlug: string | null = null
let chatPlanFile: string | null = null
let savedChat = ''

// ── Loading documents ─────────────────────────────────────────────────

async function setDoc($: $, source: Source, doc: Doc) {
  await update($, docsA, docs => ({ ...docs, [source]: doc }))
}

async function refreshChat($: $) {
  const messages = await $.session.messages().catch(() => [])
  const { doc, index } = chatDoc(messages)
  await setDoc($, 'chat', doc)
  await update($, chatIndexA, () => index)
  // Once the chat has comments in crit, each turn is a new plan version.
  if (savedChat !== '') {
    await saveChatPlan($)
  }
}

async function git($: $, argv: string[]) {
  return $.process.run(['git', ...argv], { timeoutMs: 15000 })
}

async function refreshDiff($: $) {
  const inside = await git($, ['rev-parse', '--is-inside-work-tree']).catch(() => null)
  if (!inside || inside.exitCode !== 0) {
    await setDoc($, 'diff', emptyDoc('diff', 'Diff', 'Not a git repository.'))
    return
  }

  let tracked = await git($, ['diff', 'HEAD', '--no-color', '--no-ext-diff', '-U3'])
  if (tracked.exitCode !== 0) {
    tracked = await git($, ['diff', '--no-color', '--no-ext-diff', '-U3'])
  }

  const others = await git($, ['ls-files', '--others', '--exclude-standard'])
  const untracked = others.stdout.split('\n').filter(Boolean).slice(0, MAX_UNTRACKED)
  const added = await Promise.all(
    untracked.map(path =>
      git($, ['diff', '--no-color', '--no-index', '--', '/dev/null', path])
        .then(run => run.stdout)
        .catch(() => ''),
    ),
  )

  const rows = parseDiff([tracked.stdout, ...added].join('\n'))
  const files = rows.filter(row => row.kind === 'title').length
  await setDoc(
    $,
    'diff',
    rows.length === 0
      ? emptyDoc('diff', 'Diff', 'No uncommitted changes.')
      : { source: 'diff', title: `${files} file${files === 1 ? '' : 's'} changed`, rows },
  )
}

async function refreshFile($: $, path: string) {
  try {
    await setDoc($, 'file', fileDoc(path, await $.fs.read(path)))
  } catch (error) {
    await setDoc($, 'file', emptyDoc('file', path, `Cannot read ${path}: ${String(error)}`))
  }
}

async function refreshSource($: $, source: Source) {
  if (source === 'chat') {
    await refreshChat($)
  } else if (source === 'diff') {
    await refreshDiff($)
  } else {
    const { filePath } = await readUi($)
    if (filePath) {
      await refreshFile($, filePath)
    }
  }
}

// ── crit's review file ────────────────────────────────────────────────

async function crit($: $, argv: string[], stdin?: string) {
  const run = await $.process.run([critBin, ...argv], { timeoutMs: 15000, ...(stdin ? { stdin } : {}) })
  if (run.exitCode !== 0) {
    throw new Error((run.stderr || run.stdout).trim() || `crit ${argv[0]} failed`)
  }
  return run.stdout
}

async function refreshCrit($: $) {
  if (!hasCrit) {
    return
  }
  try {
    if (!reviewFile) {
      const status = JSON.parse(await crit($, ['status', '--json'])) as { review_file?: string }
      reviewFile = status.review_file ?? null
    }
    const code = reviewFile ? critThreadsOf(await $.fs.read(reviewFile).catch(() => '')) : []
    const chat = await readChatPlanThreads($)
    await update($, critThreadsA, () => [...code, ...chat])
  } catch {
    hasCrit = false
  }
}

// ── The conversation as a crit plan ─────────────────────────────────────

async function chatPlanReady($: $): Promise<boolean> {
  if (!hasCrit) {
    return false
  }
  if (hasChatPlans === null) {
    const help = await $.process.run([critBin, 'plan', '--help'], { timeoutMs: 15000 }).catch(() => null)
    hasChatPlans = help !== null && `${help.stdout}${help.stderr}`.includes('--no-wait')
  }
  if (hasChatPlans && !chatSlug) {
    chatSlug = chatPlanSlug(await $.session.id())
    const home = await $.env.get('HOME')
    chatPlanFile = home ? `${home}/.crit/plans/${chatSlug}/.crit/review.json` : null
  }
  return hasChatPlans
}

/** Saves the conversation as the plan's next version (crit adds none when unchanged). */
async function saveChatPlan($: $) {
  if (!(await chatPlanReady($)) || !chatSlug) {
    return
  }
  const markdown = chatMarkdownOf((await read($, docsA)).chat)
  if (markdown === savedChat) {
    return
  }
  await crit($, ['plan', '--name', chatSlug, '--no-wait', '--quiet'], markdown)
  savedChat = markdown
}

async function readChatPlanThreads($: $): Promise<Thread[]> {
  if (!(await chatPlanReady($)) || !chatPlanFile) {
    return []
  }
  const json = await $.fs.read(chatPlanFile).catch(() => '')
  if (json === '') {
    return []
  }
  // A plan from earlier in this session: keep saving it each turn.
  if (savedChat === '') {
    savedChat = 'saved'
  }
  return chatThreadsFromPlan(critThreadsOf(json), (await read($, docsA)).chat.rows)
}

/** `crit comment` arguments that point at the chat plan for a chat thread. */
function planArgs(thread: Pick<Thread, 'kind'>): string[] {
  return thread.kind === 'chat' && chatSlug ? ['--plan', chatSlug] : []
}

// ── Review state ──────────────────────────────────────────────────────

async function allThreads($: $) {
  return [...(await read($, threadsA)), ...(await read($, critThreadsA))]
}

function threadsFor(source: Source, local: readonly Thread[], fromCrit: readonly Thread[]) {
  const kind = source === 'chat' ? 'chat' : 'code'
  return [...fromCrit, ...local].filter(thread => thread.kind === kind)
}

async function sync($: $) {
  const threads = await allThreads($)
  const pending = pendingOf(threads, await read($, sentA), await read($, seenA))
  const drafts = pending.comments.length + pending.replies.length
  const parts = [drafts ? `${drafts} to send` : '', pending.unread ? `${pending.unread} new from Claude` : '']
  const text = parts.filter(Boolean).join(' · ')
  $.ui.status(text ? `crit: ${text}` : undefined)
}

async function markSeen($: $) {
  const ids = claudeIdsOf(await allThreads($))
  await update($, seenA, seen => [...new Set([...seen, ...ids])])
}

async function findThread($: $, id: string): Promise<Thread | undefined> {
  const threads = await allThreads($)
  return threads.find(thread => thread.id === id) ?? threads.find(thread => id.length >= 4 && thread.id.startsWith(id))
}

async function addReply($: $, thread: Thread, body: string, who: 'you' | 'claude', resolve: boolean) {
  if ((await read($, critThreadsA)).some(one => one.id === thread.id)) {
    const argv = ['comment', ...planArgs(thread), '--reply-to', thread.id, ...(who === 'claude' ? ['--author', 'Claude'] : []), ...(resolve ? ['--resolve'] : []), body]
    await crit($, argv)
    await refreshCrit($)
    return
  }
  await update($, threadsA, list =>
    list.map(one =>
      one.id === thread.id
        ? {
            ...one,
            resolved: resolve ? true : one.resolved,
            replies: [
              ...one.replies,
              { id: newId(), author: who, body, at: new Date().toISOString(), fromClaude: who === 'claude' },
            ],
          }
        : one,
    ),
  )
}

// ── Pane actions, mostly asked for by the Client ──────────────────────

/** The pane's settings, filled in from the defaults (an older build stored fewer fields). */
async function readUi($: $): Promise<UiState> {
  return { ...EMPTY_UI, ...(await read($, uiA)) }
}

async function setUi($: $, fn: (ui: UiState) => UiState) {
  await update($, uiA, now => fn({ ...EMPTY_UI, ...now }))
}

async function openSource($: $, source: Source) {
  const ui = await readUi($)
  if (source === 'file' && !ui.filePath) {
    $.ui.toast('Open a file first: /crit-tui file <path>')
    return
  }
  await refreshSource($, source)
  const doc = (await read($, docsA))[source]
  const startAt = source === 'chat' ? sectionBefore(doc.rows, doc.rows.length) : 0
  await setUi($, now => ({ ...now, source, startAt, center: startAt, docRev: now.docRev + 1 }))
}

async function openPane($: $, source?: Source) {
  const ui = await readUi($)
  if (source || ui.docRev === 0) {
    await openSource($, source ?? ui.source)
  } else {
    await refreshSource($, ui.source)
  }
  await refreshCrit($)
  await update($, isOpenA, () => true)
  // Inline above the prompt a pane opens a third of the screen tall; ask for more.
  await $.ui.open({ id: PANE, title: 'crit', focus: true, rows: 28 })
  await markSeen($)
  await sync($)
}

async function addComment($: $, start: number, end: number, body: string, cols?: { startCol: number | null; endCol: number | null }) {
  const ui = await readUi($)
  const picked = selectionOf((await read($, docsA))[ui.source], start, end, cols)
  if (typeof picked === 'string') {
    $.ui.toast(picked)
    return
  }
  const isChat = picked.path.startsWith('chat:')
  const doc = (await read($, docsA))[ui.source]
  if (isChat && (await chatPlanReady($)) && chatSlug) {
    // Chat comments go to the plan: its line numbers are row indices plus one.
    await saveChatPlan($)
    const lo = Math.min(start, end)
    const hi = Math.max(start, end)
    const lines = doc.rows.slice(lo, hi + 1).map(row => `${chatLinePrefix(row)}${row.text}`)
    const firstPrefix = doc.rows[lo] ? chatLinePrefix(doc.rows[lo]) : ''
    const offset = picked.isExact && cols?.startCol != null ? quoteOffsetOf(lines, cols.startCol + firstPrefix.length, picked.quote) : undefined
    const entry = {
      file: `${chatSlug}.md`,
      line: lo === hi ? lo + 1 : `${lo + 1}-${hi + 1}`,
      body,
      ...(picked.isExact && picked.quote ? { quote: picked.quote } : {}),
      ...(offset !== undefined ? { quote_offset: offset } : {}),
    }
    await crit($, ['comment', '--plan', chatSlug, '--json'], JSON.stringify([entry]))
    await refreshCrit($)
    return
  }
  if (!isChat && hasCrit) {
    const line = picked.start === picked.end ? picked.start : `${picked.start}-${picked.end}`
    // An exact selection carries crit's quote fields, as a web UI selection does.
    const lines = doc.rows
      .filter(row => row.path === picked.path && row.line !== undefined && row.line >= picked.start && row.line <= picked.end && row.sign !== '-')
      .map(row => row.text)
    const offset = picked.isExact && cols?.startCol != null ? quoteOffsetOf(lines, cols.startCol, picked.quote) : undefined
    const entry = {
      file: picked.path,
      line,
      body,
      ...(picked.isExact && picked.quote ? { quote: picked.quote } : {}),
      ...(offset !== undefined ? { quote_offset: offset } : {}),
    }
    await crit($, ['comment', '--json'], JSON.stringify([entry]))
    await refreshCrit($)
    return
  }
  const { isExact: _isExact, ...anchor } = picked
  const thread: Thread = {
    id: newId(),
    kind: isChat ? 'chat' : 'code',
    ...anchor,
    body,
    author: 'you',
    fromClaude: false,
    at: new Date().toISOString(),
    resolved: false,
    replies: [],
  }
  await update($, threadsA, list => [...list, thread])
}

async function replyAsYou($: $, id: string, body: string) {
  const thread = await findThread($, id)
  if (thread) {
    await addReply($, thread, body, 'you', false)
  }
}

async function toggleResolve($: $, id: string) {
  const target = await findThread($, id)
  if (!target) {
    return
  }
  const isLocal = (await read($, threadsA)).some(one => one.id === target.id)
  if (isLocal) {
    await update($, threadsA, list => list.map(one => (one.id === target.id ? { ...one, resolved: !one.resolved } : one)))
  } else if (!target.resolved) {
    await crit($, ['comment', ...planArgs(target), '--reply-to', target.id, '--resolve', 'Resolved.'])
    await refreshCrit($)
  } else {
    $.ui.toast('Reopen this one in the crit browser view.')
  }
}

type ClientMessage = {
  type?: string
  center?: number
  start?: number
  end?: number
  startCol?: number | null
  endCol?: number | null
  body?: string
  id?: string
  source?: string
}

const isSource = (value: unknown): value is Source => value === 'chat' || value === 'diff' || value === 'file'

async function onClientMessage($: $, data: unknown) {
  const message = (data ?? {}) as ClientMessage
  try {
    switch (message.type) {
      case 'window':
        if (typeof message.center === 'number') {
          const center = message.center
          await setUi($, now => ({ ...now, center }))
        }
        return
      case 'comment':
        if (typeof message.start === 'number' && typeof message.end === 'number' && message.body) {
          const cols = typeof message.startCol === 'number' && typeof message.endCol === 'number' ? { startCol: message.startCol, endCol: message.endCol } : undefined
          await addComment($, message.start, message.end, message.body, cols)
        }
        break
      case 'reply':
        if (message.id && message.body) {
          await replyAsYou($, message.id, message.body)
        }
        break
      case 'resolve':
        if (message.id) {
          await toggleResolve($, message.id)
        }
        break
      case 'send':
        await send($)
        break
      case 'ask':
        await askForReview($)
        break
      case 'seen':
        break
      case 'toggleResolved':
        await setUi($, now => ({ ...now, resolvedView: now.resolvedView === 'line' ? 'hidden' : now.resolvedView === 'hidden' ? 'full' : 'line' }))
        break
      case 'refresh':
        await refreshSource($, (await readUi($)).source)
        await refreshCrit($)
        break
      case 'source':
        if (isSource(message.source)) {
          await openSource($, message.source)
        }
        break
    }
  } catch (error) {
    $.ui.toast(`crit: ${String(error).slice(0, 160)}`)
  }
  await markSeen($)
  await sync($)
}

async function send($: $) {
  const threads = await allThreads($)
  const pending = pendingOf(threads, await read($, sentA), await read($, seenA))
  if (pending.comments.length + pending.replies.length === 0) {
    $.ui.toast('Nothing new to send.')
    return
  }
  const text = feedbackOf(pending, await read($, chatIndexA))
  const ids = [...pending.comments.map(one => one.id), ...pending.replies.map(one => one.reply.id)]
  await update($, sentA, sent => [...new Set([...sent, ...ids])])
  await $.prompt.submit({ text, asUser: true })
  $.ui.toast(`Sent ${ids.length} item${ids.length === 1 ? '' : 's'} to Claude.`)
  await sync($)
}

async function askForReview($: $) {
  await $.prompt.submit({
    text: [
      'Review the uncommitted changes (git diff HEAD, plus new files).',
      `Leave each finding as an inline comment with the ${TOOL_PREFIX}comment tool: file, line (new-side line number), optional end_line, and a short body.`,
      'Do not change any code yet. I will reply to your comments in the crit pane.',
    ].join(' '),
    asUser: true,
  })
  $.ui.toast('Asked Claude to review the diff.')
}

export const register: Register = (on, options) => {
  critBin = typeof options.critBin === 'string' && options.critBin !== '' ? options.critBin : 'crit'
  reviewFile = null
  hasCrit = true

  // ── Session ───────────────────────────────────────────────────────────

  on('session.start', async ($, e, next) => {
    const started = await next(e)

    await $.command.register({
      name: 'crit-tui',
      description: 'crit: review the chat, your diff or a file, in a pane',
      argumentHint: '[chat|diff|file <path>|send|close]',
      immediate: true,
    })

    await $.tool.register({
      name: 'reply',
      description:
        'Reply to a crit review comment the user left (on the conversation, the diff or a file). Pass the comment id from the review and a short reply. The user resolves threads, not you.',
      inputSchema: {
        type: 'object',
        properties: {
          id: { type: 'string', description: 'The comment id, as given in the review.' },
          body: { type: 'string', description: 'Your reply.' },
        },
        required: ['id', 'body'],
      },
    })

    await $.tool.register({
      name: 'comment',
      description:
        'Leave an inline crit review comment on a line of a file in the repository (new-side line numbers for diffs). The user reads it in the crit pane and can reply.',
      inputSchema: {
        type: 'object',
        properties: {
          file: { type: 'string', description: 'Path relative to the repository root.' },
          line: { type: 'integer', minimum: 1 },
          end_line: { type: 'integer', minimum: 1 },
          body: { type: 'string' },
        },
        required: ['file', 'line', 'body'],
      },
    })

    await $.tool.register({
      name: 'threads',
      description: 'List open crit review threads (comments and replies) with their ids.',
      inputSchema: { type: 'object', properties: { include_resolved: { type: 'boolean' } } },
    })

    await refreshCrit($)
    await sync($)

    return started
  })

  on('command.run', { command: 'crit-tui' }, async ($, e) => {
    const [word = '', ...rest] = e.args.trim().split(/\s+/)
    const arg = rest.join(' ')

    switch (word) {
      case 'send':
        await send($)
        return { text: 'crit: review sent.' }
      case 'close':
        await $.ui.close({ id: PANE })
        await update($, isOpenA, () => false)
        return { text: 'crit pane closed.' }
      case 'file': {
        if (!arg) {
          return { text: 'Usage: /crit-tui file <path>' }
        }
        await setUi($, now => ({ ...now, filePath: arg }))
        await openPane($, 'file')
        return { text: `crit: reviewing ${arg}.` }
      }
      case 'chat':
      case 'diff':
        await openPane($, word)
        return { text: `crit: reviewing the ${word === 'chat' ? 'conversation' : 'diff'}.` }
      case '':
        await openPane($)
        return { text: 'crit pane open. Click it to give it the keys.' }
      default:
        return { text: `Unknown /crit-tui argument "${word}". Try chat, diff, file <path>, send or close.` }
    }
  })

  on('ui.close', { id: PANE }, async ($, e, next) => {
    await update($, isOpenA, () => false)
    return next(e)
  })

  // ── Tools Claude calls ────────────────────────────────────────────────

  on('tool.call', { tool: 'mcp__crit-tui__reply' }, async ($, e) => {
    const input = e as unknown as { id?: string; body?: string }
    const thread = input.id ? await findThread($, input.id) : undefined
    if (!thread || !input.body) {
      return { deny: `No crit thread with id ${input.id ?? '(none)'}. Call ${TOOL_PREFIX}threads to list them.` }
    }
    try {
      await addReply($, thread, input.body, 'claude', false)
    } catch (error) {
      return { deny: `crit could not save the reply: ${String(error)}` }
    }
    $.ui.toast(`Claude replied on ${whereOf(thread, await read($, chatIndexA))}`)
    await sync($)
    return { result: 'Reply saved. The user sees it in the crit pane.' }
  })

  on('tool.call', { tool: 'mcp__crit-tui__comment' }, async ($, e) => {
    const input = e as unknown as { file?: string; line?: number; end_line?: number; body?: string }
    if (!input.file || !input.line || !input.body) {
      return { deny: 'file, line and body are required.' }
    }
    const end = input.end_line && input.end_line > input.line ? input.end_line : input.line
    try {
      if (hasCrit) {
        await crit($, ['comment', '--author', 'Claude', `${input.file}:${input.line}${end !== input.line ? `-${end}` : ''}`, input.body])
        await refreshCrit($)
      } else {
        const thread: Thread = {
          id: newId(),
          kind: 'code',
          path: input.file,
          start: input.line,
          end,
          quote: '',
          body: input.body,
          author: 'claude',
          fromClaude: true,
          at: new Date().toISOString(),
          resolved: false,
          replies: [],
        }
        await update($, threadsA, list => [...list, thread])
      }
    } catch (error) {
      return { deny: `crit could not save the comment: ${String(error)}` }
    }
    await sync($)
    return { result: `Comment left on ${input.file}:${input.line}.` }
  })

  on('tool.call', { tool: 'mcp__crit-tui__threads' }, async ($, e) => {
    const input = e as unknown as { include_resolved?: boolean }
    const index = await read($, chatIndexA)
    const threads = (await allThreads($)).filter(thread => input.include_resolved || !thread.resolved)
    if (threads.length === 0) {
      return { result: 'No open crit threads.' }
    }
    const text = threads
      .map(thread =>
        [
          `[id ${thread.id}] ${whereOf(thread, index)}${thread.resolved ? ' (resolved)' : ''}`,
          `  ${thread.fromClaude ? 'claude' : 'user'}: ${thread.body}`,
          ...thread.replies.map(reply => `  ${reply.fromClaude ? 'claude' : 'user'}: ${reply.body}`),
        ].join('\n'),
      )
      .join('\n\n')
    return { result: text }
  })

  // ── Keeping documents fresh ───────────────────────────────────────────

  on('tool.call', { tool: ['Edit', 'Write', 'NotebookEdit'] }, async ($, e, next) => {
    const ran = await next(e)
    if ((await read($, isOpenA)) && (await readUi($)).source === 'diff') {
      diffTimer?.cancel()
      diffTimer = $.clock.after(500, () => {
        void refreshDiff($)
      })
    }
    return ran
  })

  on('turn.complete', async ($, e, next) => {
    const done = await next(e)
    await refreshChat($)
    await refreshCrit($)
    if ((await read($, isOpenA)) && (await readUi($)).source === 'diff') {
      await refreshDiff($)
    }
    await sync($)
    return done
  })

  // ── The Client's messages, and the wheel over the pane ────────────────

  on('ui.message', { requestId: PANE }, async ($, e) => {
    await onClientMessage($, e.data)
    return {}
  })

  on('ui.scroll', { requestId: PANE }, async ($, e, next) => {
    if (e.origin.kind !== 'person') {
      return next(e)
    }
    const by = e.by
    await setUi($, now => ({ ...now, wheel: now.wheel + 1, wheelBy: by }))
    return {}
  })

  // ── The pane: one Client that owns keys, mouse and drawing ────────────

  on('ui.render', { component: 'Pane', requestId: PANE }, async ($, e) => {
    if (e.surface === 'mobile' || e.surface === 'vscode') {
      const { Text } = $.ui.resolve(e)
      return <Text dimColor>crit-tui needs the terminal or the desktop app.</Text>
    }

    const { Client } = $.ui.resolve(e)
    const ui = await readUi($)
    const local = await read($, threadsA)
    const fromCrit = await read($, critThreadsA)
    const sent = await read($, sentA)
    const seen = await read($, seenA)
    const pending = pendingOf([...local, ...fromCrit], sent, seen)
    const drafts = pending.comments.length + pending.replies.length
    const status = hasCrit ? '' : 'no crit review file: code comments stay here'

    const props = clientPropsOf({
      doc: (await read($, docsA))[ui.source],
      threads: threadsFor(ui.source, local, fromCrit),
      ui,
      sent,
      seen,
      status,
      toSend: drafts,
      unread: pending.unread,
    })

    return (
      <Client
        key="review"
        module="./client.tsx"
        props={props}
        width={Math.max(30, e.props.bodyColumns)}
        height={Math.max(6, e.props.scroll.bodyRows)}
      />
    )
  })

  // ── The band above the prompt while the pane is closed ────────────────

  on('ui.render', { component: 'AbovePrompt' }, async ($, e, next) => {
    if (e.props.hasSurvey || (await read($, isOpenA))) {
      return next(e)
    }
    const pending = pendingOf(await allThreads($), await read($, sentA), await read($, seenA))
    const drafts = pending.comments.length + pending.replies.length
    if (drafts === 0 && pending.unread === 0) {
      return next(e)
    }
    const { Box, Text, Button } = $.ui.resolve(e)
    const parts = [
      drafts ? `${drafts} comment${drafts === 1 ? '' : 's'} to send` : '',
      pending.unread ? `${pending.unread} new from Claude` : '',
    ]
    return (
      <Box flexDirection="row" gap={2}>
        <Text color="magenta">crit</Text>
        <Text dimColor>{parts.filter(Boolean).join(' · ')}</Text>
        {drafts > 0 && <Button key="band-send" hotkey="s" label="send" variant="primary" onPress={() => void send($)} />}
        <Button key="band-open" hotkey="o" label="open" onPress={() => void openPane($)} />
      </Box>
    )
  })

  // ── A note under replies that have comments ───────────────────────────

  on('ui.render', { component: 'AssistantMessage' }, async ($, e, next) => {
    const text = e.props.text.trim()
    if (text === '') {
      return next(e)
    }
    const index = await read($, chatIndexA)
    const probe = text.slice(0, 200)
    const entry = index.find(one => one.role === 'assistant' && one.text.includes(probe))
    if (!entry) {
      return next(e)
    }
    const all = [...(await read($, threadsA)), ...(await read($, critThreadsA))]
    const mine = all.filter(thread => thread.path === `chat:${entry.index}`)
    if (mine.length === 0) {
      return next(e)
    }
    const open = mine.filter(thread => !thread.resolved).length
    const replies = mine.reduce((sum, thread) => sum + thread.replies.length, 0)
    const drawn = await next(e)
    const { Box, Text } = $.ui.resolve(e)
    return (
      <Box flexDirection="column">
        {drawn}
        <Text color="magenta" dimColor>
          {'  '}💬 {mine.length} crit comment{mine.length === 1 ? '' : 's'} · {open} open
          {replies ? ` · ${replies} repl${replies === 1 ? 'y' : 'ies'}` : ''} · /crit-tui to open
        </Text>
      </Box>
    )
  }).catch(($, e, next) => next(e))
}

files.hooks/model.ts:
import type { SessionMessage } from 'claude-code'

import type { ChatIndex, ClientRow, ClientThread, Doc, Reply, ReviewProps, Row, Source, Thread, UiState } from '../types'

export const TOOL_PREFIX = 'mcp__crit-tui__'
const MAX_ROWS = 6000
const TOOL_OUTPUT_LINES = 6

export const EMPTY_UI: UiState = {
  source: 'chat',
  startAt: 0,
  center: 0,
  resolvedView: 'line',
  filePath: null,
  docRev: 0,
  wheel: 0,
  wheelBy: 0,
}

export const emptyDoc = (source: Source, title: string, error?: string): Doc => ({
  source,
  title,
  rows: [],
  ...(error ? { error } : {}),
})

const ANSI = /\u001b\[[0-9;?]*[ -/]*[@-~]/g

const stripAnsi = (text: string) => text.replace(ANSI, '').replace(/\t/g, '  ')

const isClaude = (author: string) => /claude/i.test(author)

// ── Documents ───────────────────────────────────────────────────────────

/**
 * Turns `git diff` output into rows. `+` and context lines anchor to their
 * new line number; a `-` line anchors to the new-side position it sits at.
 */
export function parseDiff(text: string): Row[] {
  const rows: Row[] = []
  let path = ''
  let oldLine = 0
  let newLine = 0

  for (const raw of text.split('\n')) {
    if (rows.length >= MAX_ROWS) {
      rows.push({ kind: 'note', text: '… diff cut here' })
      break
    }

    if (raw.startsWith('diff --git ')) {
      const match = / b\/(.+)$/.exec(raw)
      path = match?.[1] ?? raw.slice(11)
      rows.push({ kind: 'title', text: path, path })
      continue
    }

    if (raw.startsWith('+++ ')) {
      const next = raw.slice(4).replace(/^b\//, '')
      if (next !== '/dev/null' && next !== path) {
        path = next
        const title = [...rows].reverse().find(row => row.kind === 'title')
        if (title) {
          title.text = path
          title.path = path
        }
      }
      continue
    }

    if (/^(--- |index |new file mode|deleted file mode|similarity |rename |old mode|new mode)/.test(raw)) {
      continue
    }

    const hunk = /^@@ -(\d+)(?:,\d+)? \+(\d+)(?:,\d+)? @@(.*)$/.exec(raw)
    if (hunk) {
      oldLine = Number(hunk[1])
      newLine = Number(hunk[2])
      rows.push({ kind: 'hunk', text: `@@ -${hunk[1]} +${hunk[2]} @@${hunk[3]}` })
      continue
    }

    if (raw.startsWith('Binary files')) {
      rows.push({ kind: 'note', text: raw })
      continue
    }

    if (raw.startsWith('\\') || path === '') {
      continue
    }

    const sign = raw[0]
    const body = stripAnsi(raw.slice(1))

    if (sign === '+') {
      rows.push({ kind: 'line', sign: '+', text: body, path, line: newLine, no: String(newLine) })
      newLine += 1
    } else if (sign === '-') {
      rows.push({ kind: 'line', sign: '-', text: body, path, line: Math.max(1, newLine), no: '' })
      oldLine += 1
    } else if (sign === ' ') {
      rows.push({ kind: 'line', sign: ' ', text: body, path, line: newLine, no: String(newLine) })
      newLine += 1
      oldLine += 1
    }
  }

  return rows
}

/** One line telling what a tool call did. */
const REVIEW_HEAD = 'Crit review:'

/** This mod's own tool calls, and the lookup that loads them, are left out of the chat. */
function isCritPlumbing(tool: string, input: Record<string, unknown>): boolean {
  if (tool.startsWith(TOOL_PREFIX)) return true
  return tool === 'ToolSearch' && typeof input.query === 'string' && input.query.includes('crit-tui')
}

function toolSummary(tool: string, input: Record<string, unknown>): string {
  const pick = (key: string) => (typeof input[key] === 'string' ? (input[key] as string) : '')
  const arg =
    pick('command') ||
    pick('file_path') ||
    pick('pattern') ||
    pick('path') ||
    pick('url') ||
    pick('description') ||
    JSON.stringify(input)

  const name = tool.startsWith('mcp__') ? tool.split('__').slice(1).join(':') : tool

  return `${name}(${arg.replace(/\s+/g, ' ').slice(0, 120)})`
}

/**
 * The conversation as rows: a title per message, its text lines anchored to
 * `chat:<index>`, and each tool call with the head of its output, anchored
 * to `chat:<index>/<tool_use_id>`.
 */
export function chatDoc(messages: readonly SessionMessage[]): { doc: Doc; index: ChatIndex } {
  const rows: Row[] = []
  const index: ChatIndex = []

  messages.forEach((message, at) => {
    const text = message.text.trim()
    const tools = message.toolUses.filter(use => !isCritPlumbing(use.tool, use.input))
    const hasTools = tools.length > 0

    // The review this mod sent shows as one line, not the whole prompt.
    if (message.role === 'user' && text.startsWith(REVIEW_HEAD)) {
      rows.push({ kind: 'note', text: `↳ you sent a crit review: ${text.split('\n')[0]?.slice(REVIEW_HEAD.length).trim()}`, role: 'user' })
      return
    }

    if (text === '' && !hasTools) {
      return
    }

    const path = `chat:${at}`

    if (text !== '') {
      index.push({ index: at, role: message.role, text })
      rows.push({
        kind: 'title',
        text: message.role === 'user' ? `you · #${at}` : `claude · #${at}`,
        role: message.role,
        path,
      })
      text.split('\n').forEach((line, n) => {
        rows.push({ kind: 'line', text: stripAnsi(line), role: message.role, path, line: n + 1, no: String(n + 1) })
      })
    }

    for (const use of tools) {
      const toolPath = `${path}/${use.tool_use_id}`
      rows.push({ kind: 'hunk', text: `⏺ ${toolSummary(use.tool, use.input)}`, role: 'tool', path: toolPath })

      const output = stripAnsi(use.text ?? '').split('\n').filter(line => line.trim() !== '')
      output.slice(0, TOOL_OUTPUT_LINES).forEach((line, n) => {
        rows.push({ kind: 'line', text: line, role: 'tool', path: toolPath, line: n + 1, no: use.isError ? '!' : '' })
      })
      if (output.length > TOOL_OUTPUT_LINES) {
        rows.push({ kind: 'note', text: `  … ${output.length - TOOL_OUTPUT_LINES} more lines`, role: 'tool' })
      }
    }
  })

  const doc: Doc =
    rows.length === 0
      ? emptyDoc('chat', 'Conversation', 'Nothing said yet.')
      : { source: 'chat', title: 'Conversation', rows }

  return { doc, index }
}

export function fileDoc(path: string, content: string): Doc {
  const lines = content.split('\n')
  if (lines.at(-1) === '') {
    lines.pop()
  }

  const rows: Row[] = [{ kind: 'title', text: path, path }]
  lines.slice(0, MAX_ROWS).forEach((line, n) => {
    rows.push({ kind: 'line', text: stripAnsi(line), path, line: n + 1, no: String(n + 1) })
  })

  return { source: 'file', title: path, rows }
}

// ── crit's review.json ──────────────────────────────────────────────────

type CritReply = { id?: string; body?: string; author?: string; created_at?: string }
type CritComment = CritReply & {
  start_line?: number
  end_line?: number
  quote?: string
  anchor?: string
  resolved?: boolean
  replies?: CritReply[]
}

/** Reads crit's review.json into code threads. */
export function critThreadsOf(json: string): Thread[] {
  let parsed: unknown
  try {
    parsed = JSON.parse(json)
  } catch {
    return []
  }

  const files = (parsed as { files?: Record<string, { comments?: CritComment[] }> })?.files ?? {}
  const threads: Thread[] = []

  for (const [path, file] of Object.entries(files)) {
    for (const comment of file?.comments ?? []) {
      if (!comment.id) {
        continue
      }
      const author = comment.author ?? 'you'
      threads.push({
        id: comment.id,
        kind: 'code',
        path,
        start: comment.start_line ?? 0,
        end: comment.end_line ?? comment.start_line ?? 0,
        quote: comment.quote || comment.anchor || '',
        body: comment.body ?? '',
        author,
        fromClaude: isClaude(author),
        at: comment.created_at ?? '',
        resolved: comment.resolved === true,
        replies: (comment.replies ?? []).map(
          (reply): Reply => ({
            id: reply.id ?? '',
            author: reply.author ?? 'you',
            body: reply.body ?? '',
            at: reply.created_at ?? '',
            fromClaude: isClaude(reply.author ?? ''),
          }),
        ),
      })
    }
  }

  return threads
}

// ── The conversation as a crit plan ─────────────────────────────────────

/** The plan a session's chat comments live in. */
export const chatPlanSlug = (sessionId: string) => `claude-chat-${sessionId.replace(/[^a-z0-9]/gi, '').slice(0, 8).toLowerCase()}`

/** What a chat row adds before its text in the saved markdown. */
export function chatLinePrefix(row: Row): string {
  if (row.kind === 'title') return '### '
  if (row.role === 'tool' || row.kind === 'note') return '> '
  return ''
}

/**
 * The conversation as markdown for `crit plan`: row i is line i + 1, so a
 * comment's line numbers in crit are row indices plus one.
 */
export function chatMarkdownOf(doc: Doc): string {
  return doc.rows.map(row => `${chatLinePrefix(row)}${row.text}`.replace(/\s+$/, '')).join('\n') + '\n'
}

/** Plan threads (lines of the saved markdown) put back on their messages. */
export function chatThreadsFromPlan(planThreads: readonly Thread[], rows: readonly Row[]): Thread[] {
  return planThreads.map(thread => {
    const first = rows[thread.start - 1]
    const last = rows[thread.end - 1]
    if (!last?.path) {
      return { ...thread, kind: 'chat' }
    }
    const start = first?.path === last.path ? (first.line ?? 0) : (last.line ?? 0)
    return { ...thread, kind: 'chat', path: last.path, start, end: last.line ?? 0 }
  })
}

// ── Review state ────────────────────────────────────────────────────────

export type Pending = {
  comments: Thread[]
  replies: { thread: Thread; reply: Reply }[]
  unread: number
}

/** What the person wrote that Claude has not seen, and what Claude wrote that the person has not. */
export function pendingOf(threads: readonly Thread[], sent: readonly string[], seen: readonly string[]): Pending {
  const isSent = new Set(sent)
  const isSeen = new Set(seen)
  const comments: Thread[] = []
  const replies: { thread: Thread; reply: Reply }[] = []
  let unread = 0

  for (const thread of threads) {
    if (thread.fromClaude && !isSeen.has(thread.id)) {
      unread += 1
    }
    for (const reply of thread.replies) {
      if (reply.fromClaude && !isSeen.has(reply.id)) {
        unread += 1
      }
    }
    if (thread.resolved) {
      continue
    }
    if (!thread.fromClaude && !isSent.has(thread.id)) {
      comments.push(thread)
    }
    for (const reply of thread.replies) {
      if (!reply.fromClaude && !isSent.has(reply.id) && reply.id !== '') {
        replies.push({ thread, reply })
      }
    }
  }

  return { comments, replies, unread }
}

/** Every Claude-authored id, to mark as seen. */
export const claudeIdsOf = (threads: readonly Thread[]) =>
  threads.flatMap(thread => [
    ...(thread.fromClaude ? [thread.id] : []),
    ...thread.replies.filter(reply => reply.fromClaude).map(reply => reply.id),
  ])

export function whereOf(thread: Pick<Thread, 'path' | 'start' | 'end'>, index: ChatIndex = []): string {
  const lines =
    thread.end === 0 ? 'as a whole' : thread.start === thread.end ? `line ${thread.start}` : `lines ${Math.max(1, thread.start)}-${thread.end}`
  const chat = /^chat:(\d+)(?:\/(.+))?$/.exec(thread.path)
  if (!chat) {
    return thread.start > 0 ? `${thread.path}:${thread.start}${thread.end !== thread.start ? `-${thread.end}` : ''}` : thread.path
  }
  const role = index.find(entry => entry.index === Number(chat[1]))?.role
  const whose = role === 'user' ? 'my message' : 'your reply'
  return chat[2] ? `tool output in message #${chat[1]}, ${lines}` : `${whose} #${chat[1]}${thread.end === 0 ? ' ' : ', '}${lines}`
}

const quoted = (text: string) =>
  text
    .split('\n')
    .slice(0, 8)
    .map(line => `   > ${line}`)
    .join('\n')

/** The review as one prompt for Claude. */
export function feedbackOf(pending: Pending, index: ChatIndex): string {
  const parts: string[] = []
  let n = 0

  for (const thread of pending.comments) {
    n += 1
    parts.push(
      [`${n}. ${whereOf(thread, index)} [id ${thread.id}]`, thread.quote ? quoted(thread.quote) : '', `   ${thread.body}`]
        .filter(Boolean)
        .join('\n'),
    )
  }

  for (const { thread, reply } of pending.replies) {
    n += 1
    const before = thread.replies.filter(one => one.id !== reply.id && one.at <= reply.at).at(-1)
    parts.push(
      [
        `${n}. Reply in thread [id ${thread.id}] on ${whereOf(thread, index)}`,
        `   Thread: ${thread.body}`,
        before ? `   ${before.fromClaude ? 'You' : 'I'} said: ${before.body}` : '',
        `   My reply: ${reply.body}`,
      ]
        .filter(Boolean)
        .join('\n'),
    )
  }

  const counts = [
    pending.comments.length ? `${pending.comments.length} comment${pending.comments.length === 1 ? '' : 's'}` : '',
    pending.replies.length ? `${pending.replies.length} repl${pending.replies.length === 1 ? 'y' : 'ies'}` : '',
  ]
    .filter(Boolean)
    .join(', ')

  return [
    `${REVIEW_HEAD} ${counts}.`,
    '',
    parts.join('\n\n'),
    '',
    `Reply to each item with the ${TOOL_PREFIX}reply tool: pass its id and a short reply. Make any code change an item asks for before you reply to it. I resolve threads myself. The ids are for the tool only: don't mention them in your answer to me.`,
  ].join('\n')
}

// ── What the pane's Client draws ────────────────────────────────────────

/** Characters of rows sent to the Client at once; its props are capped near 100k. */
const WINDOW_CHARS = 60000
const ROW_CHARS = 400

/** The row each thread hangs under: the last row of its range, a `+`/context line first. */
function anchorRowOf(rows: readonly Row[], thread: Thread): number {
  let fallback = -1
  for (let i = 0; i < rows.length; i += 1) {
    const row = rows[i]
    if (!row || row.path !== thread.path) {
      continue
    }
    if (row.line === thread.end || (thread.end === 0 && row.kind === 'title')) {
      if (row.sign !== '-') {
        return i
      }
      fallback = fallback === -1 ? i : fallback
    }
  }
  return fallback
}

/** The rows around `center` that fit the budget, as [from, to). */
function windowOf(rows: readonly Row[], center: number, budget = WINDOW_CHARS): [number, number] {
  const cost = (i: number) => Math.min(rows[i]?.text.length ?? 0, ROW_CHARS) + 40
  const mid = Math.min(Math.max(center, 0), Math.max(0, rows.length - 1))
  let from = mid
  let to = Math.min(mid + 1, rows.length)
  let spent = rows.length ? cost(mid) : 0
  while (spent < budget && (from > 0 || to < rows.length)) {
    if (to < rows.length) {
      spent += cost(to)
      to += 1
    }
    if (from > 0 && spent < budget) {
      from -= 1
      spent += cost(from)
    }
  }
  return [from, to]
}

/** The props of the review Client: a window of rows, the threads hung in it, and the header. */
export function clientPropsOf(args: {
  doc: Doc
  threads: readonly Thread[]
  ui: UiState
  sent: readonly string[]
  seen: readonly string[]
  status: string
  toSend?: number
  unread?: number
}): ReviewProps {
  const { doc, ui } = args
  const sent = new Set(args.sent)
  const seen = new Set(args.seen)
  const [from, to] = windowOf(doc.rows, ui.center)
  const rows: ClientRow[] = doc.rows.slice(from, to).map((row, n) => ({
    i: from + n,
    k: row.kind,
    t: row.text.slice(0, ROW_CHARS),
    c: row.path !== undefined,
    ...(row.no ? { no: row.no } : {}),
    ...(row.sign ? { s: row.sign } : {}),
    ...(row.role ? { r: row.role } : {}),
  }))

  const head = (author: string, fromClaude: boolean, id: string, resolved: boolean) =>
    [
      fromClaude ? 'claude' : author === '' ? 'you' : author,
      !fromClaude && !sent.has(id) && !resolved ? 'draft' : '',
      fromClaude && !seen.has(id) ? 'new' : '',
    ]
      .filter(Boolean)
      .join(' · ')

  let orphans = 0
  let hidden = 0
  const threads: ClientThread[] = []
  for (const thread of args.threads) {
    const row = anchorRowOf(doc.rows, thread)
    if (row === -1) {
      orphans += 1
      continue
    }
    if (row < from || row >= to) {
      continue
    }
    const isNew = thread.replies.some(reply => reply.fromClaude && !seen.has(reply.id))
    if (thread.resolved && ui.resolvedView === 'hidden' && !isNew) {
      hidden += 1
      continue
    }
    if (thread.resolved && ui.resolvedView !== 'full') {
      const lastWord = thread.replies.at(-1)
      threads.push({
        id: thread.id,
        row,
        tone: isNew ? 'claude' : 'you',
        head: `✓ resolved${isNew ? ' · new' : ''} · ${thread.body.split('\n')[0]?.slice(0, 40) ?? ''}${lastWord ? ` → ${lastWord.fromClaude ? 'claude' : 'you'}: ${lastWord.body.split('\n')[0]?.slice(0, 80) ?? ''}` : ''}`,
        body: '',
        replies: [],
        collapsed: true,
      })
      continue
    }
    threads.push({
      id: thread.id,
      row,
      tone: thread.fromClaude ? 'claude' : sent.has(thread.id) || thread.resolved ? 'you' : 'draft',
      head: `${head(thread.author, thread.fromClaude, thread.id, thread.resolved)}${thread.resolved ? ' · resolved ✓' : ''}`,
      body: thread.body,
      replies: thread.replies.map(reply => ({
        tone: reply.fromClaude ? 'claude' : sent.has(reply.id) ? 'you' : 'draft',
        head: head(reply.author, reply.fromClaude, reply.id, thread.resolved),
        body: reply.body,
      })),
    })
  }

  return {
    docKey: `${ui.source}:${ui.docRev}`,
    startAt: ui.startAt,
    source: ui.source,
    title: doc.title,
    status: [args.status, orphans ? `${orphans} off-view` : '', hidden ? `${hidden} resolved hidden (h)` : ''].filter(Boolean).join(' · '),
    toSend: args.toSend ?? 0,
    unread: args.unread ?? 0,
    error: doc.error ?? null,
    total: doc.rows.length,
    rows,
    threads,
    wheel: ui.wheel,
    wheelBy: ui.wheelBy,
  }
}

// ── Selection ───────────────────────────────────────────────────────────

/** The last title row before `from`, or the first row. */
export function sectionBefore(rows: readonly Row[], from: number): number {
  for (let i = Math.min(from, rows.length) - 1; i >= 0; i -= 1) {
    if (rows[i]?.kind === 'title') {
      return i
    }
  }
  return 0
}

/**
 * The anchor a comment on rows `lo`..`hi` takes, or why it can't. With
 * columns (a mouse selection) the quote is the exact text: from `startCol`
 * in the first row to `endCol` in the last.
 */
export function selectionOf(
  doc: Doc,
  lo: number,
  hi: number,
  cols: { startCol: number | null; endCol: number | null } = { startCol: null, endCol: null },
): { path: string; start: number; end: number; quote: string; isExact: boolean } | string {
  const picked = doc.rows
    .map((row, i) => ({ row, i }))
    .slice(Math.min(lo, hi), Math.max(lo, hi) + 1)
    .filter(({ row }) => row.path !== undefined)
  if (picked.length === 0) {
    return 'Move to a line to comment on it.'
  }
  const path = picked[picked.length - 1]?.row.path as string
  const same = picked.filter(({ row }) => row.path === path)
  // A title row (line 0: the whole message or file) only counts when nothing else is picked.
  const numbered = same.map(({ row }) => row.line ?? 0).filter(line => line > 0)
  const lines = numbered.length > 0 ? numbered : [0]
  const isExact = cols.startCol !== null && cols.endCol !== null
  const quote = same
    .filter(({ row }) => row.kind === 'line')
    .map(({ row, i }) => {
      if (isExact) {
        const from = i === Math.min(lo, hi) ? (cols.startCol ?? 0) : 0
        const to = i === Math.max(lo, hi) ? (cols.endCol ?? row.text.length) : row.text.length
        return row.text.slice(from, to)
      }
      return row.sign && row.sign !== ' ' ? `${row.sign}${row.text}` : row.text
    })
    .join('\n')
  return { path, start: Math.min(...lines), end: Math.max(...lines), quote, isExact }
}

const collapse = (text: string) => text.replace(/\s+/g, ' ')

/**
 * Where an exact quote starts in its lines' text, as crit's web UI records
 * `quote_offset`: the lines trimmed and joined by newlines, whitespace
 * collapsed. Undefined when the quote is not found there.
 */
export function quoteOffsetOf(lines: readonly string[], startCol: number, quote: string): number | undefined {
  const first = lines[0] ?? ''
  const lead = first.length - first.trimStart().length
  const full = collapse(lines.map(line => line.trim()).join('\n'))
  const wanted = collapse(quote)
  const guess = collapse(first.trimStart().slice(0, Math.max(0, startCol - lead))).length
  if (full.slice(guess, guess + wanted.length) === wanted) return guess
  const found = full.indexOf(wanted)
  return found === -1 ? undefined : found
}

export function newId(): string {
  const bytes = new Uint8Array(4)
  crypto.getRandomValues(bytes)
  return 'c' + [...bytes].map(b => b.toString(16).padStart(2, '0')).join('')
}

